
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_sregtm_v2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_sregtm_v2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.654436581863981e+00, -4.561772243283905e+00, -4.431993818292547e+00, -4.252359989542322e+00, -4.007888606265586e+00, -3.683165062736294e+00, -3.266592613503121e+00, -2.757926629184522e+00, -2.177585189417424e+00, -1.568714038666309e+00, -1.009288705046157e+00, -7.060846416560441e-01, -6.029637534737441e-01, -5.110827660655182e-01, -3.670586878035905e-01, -2.263314325407840e-01, -1.198003154902635e-01, -5.402433241618001e-02, -2.012346857664212e-02, -5.340788267129101e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


